import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.DpgUYQlf.js";const u=JSON.parse('{"title":"FAQ","description":"Answers to common Nette API questions - 404 for registered endpoints, 500 for valid responses, tokens, CORS, logging, OpenAPI and upgrading.","frontmatter":{"title":"FAQ","description":"Answers to common Nette API questions - 404 for registered endpoints, 500 for valid responses, tokens, CORS, logging, OpenAPI and upgrading."},"headers":[],"relativePath":"faq.md","filePath":"faq.md","lastUpdated":1793367813000}'),n={name:"faq.md"};function i(d,e,s,h,p,l){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><h2 id="why-does-my-registered-endpoint-answer-404" tabindex="-1">Why does my registered endpoint answer 404? <a class="header-anchor" href="#why-does-my-registered-endpoint-answer-404" aria-label="Permalink to &quot;Why does my registered endpoint answer 404?&quot;">​</a></h2><p>The method, version, package and action of the request must match an <code>EndpointIdentifier</code> exactly, and the route must lead to <code>Api:Api:default</code>. See <a href="/nette-api/pr-preview/pr-235/guide/getting-started.html">Getting started</a>.</p><h2 id="my-handler-returns-the-right-data-but-the-client-gets-500-why" tabindex="-1">My handler returns the right data, but the client gets 500. Why? <a class="header-anchor" href="#my-handler-returns-the-right-data-but-the-client-gets-500-why" aria-label="Permalink to &quot;My handler returns the right data, but the client gets 500. Why?&quot;">​</a></h2><p>The response did not match any declared output, and output validation is on. Look at <code>detail</code>, or read <a href="/nette-api/pr-preview/pr-235/guide/outputs.html#when-outputs-are-validated">Outputs</a>.</p><h2 id="why-does-production-say-only-wrong-input" tabindex="-1">Why does production say only &quot;wrong input&quot;? <a class="header-anchor" href="#why-does-production-say-only-wrong-input" aria-label="Permalink to &quot;Why does production say only &quot;wrong input&quot;?&quot;">​</a></h2><p>Error details are off in production, also for <code>400</code>. See <a href="/nette-api/pr-preview/pr-235/guide/errors.html#error-details">Error handling</a>.</p><h2 id="how-do-i-protect-an-endpoint-with-a-token" tabindex="-1">How do I protect an endpoint with a token? <a class="header-anchor" href="#how-do-i-protect-an-endpoint-with-a-token" aria-label="Permalink to &quot;How do I protect an endpoint with a token?&quot;">​</a></h2><p>Use <code>BearerTokenAuthorization</code> or an API key class with a token repository. See <a href="/nette-api/pr-preview/pr-235/guide/authorization.html">Authorization</a>.</p><h2 id="why-does-my-browser-app-get-a-cors-error" tabindex="-1">Why does my browser app get a CORS error? <a class="header-anchor" href="#why-does-my-browser-app-get-a-cors-error" aria-label="Permalink to &quot;Why does my browser app get a CORS error?&quot;">​</a></h2><p>Set the allowed origin and enable preflight. See <a href="/nette-api/pr-preview/pr-235/guide/cors.html">CORS</a>.</p><h2 id="why-are-401-and-429-responses-not-in-my-log" tabindex="-1">Why are 401 and 429 responses not in my log? <a class="header-anchor" href="#why-are-401-and-429-responses-not-in-my-log" aria-label="Permalink to &quot;Why are 401 and 429 responses not in my log?&quot;">​</a></h2><p>The presenter returns before the logger in 3.x. See <a href="/nette-api/pr-preview/pr-235/guide/logging.html#what-is-logged">Logging</a>.</p><h2 id="should-i-use-problem-details" tabindex="-1">Should I use Problem Details? <a class="header-anchor" href="#should-i-use-problem-details" aria-label="Permalink to &quot;Should I use Problem Details?&quot;">​</a></h2><p>Yes, in a new project: RFC 9457 errors have one machine-readable shape. They are not the default, because existing clients read <code>message</code>. See <a href="/nette-api/pr-preview/pr-235/guide/problem-details.html">Problem Details</a>.</p><h2 id="can-i-configure-the-api-without-a-list-of-addapi-calls" tabindex="-1">Can I configure the API without a list of addApi() calls? <a class="header-anchor" href="#can-i-configure-the-api-without-a-list-of-addapi-calls" aria-label="Permalink to &quot;Can I configure the API without a list of addApi() calls?&quot;">​</a></h2><p>Yes, since 4.0.0 with the <a href="/nette-api/pr-preview/pr-235/guide/di-extension.html">DI extension</a>: one <code>api:</code> neon section with the endpoints, authorizations, rate limits, CORS and the error format, checked when the container is compiled.</p><h2 id="can-i-declare-an-endpoint-on-the-handler-class" tabindex="-1">Can I declare an endpoint on the handler class? <a class="header-anchor" href="#can-i-declare-an-endpoint-on-the-handler-class" aria-label="Permalink to &quot;Can I declare an endpoint on the handler class?&quot;">​</a></h2><p>Yes, since 4.0.0: put <code>#[Get(1, &#39;users&#39;)]</code> (or <code>Post</code>, <code>Put</code>, <code>Patch</code>, <code>Delete</code>, <code>Endpoint</code>) on the class and the DI extension registers it. See <a href="/nette-api/pr-preview/pr-235/guide/attributes.html">Attribute endpoints</a>.</p><h2 id="the-container-does-not-compile-after-i-changed-the-api-section-what-now" tabindex="-1">The container does not compile after I changed the api: section. What now? <a class="header-anchor" href="#the-container-does-not-compile-after-i-changed-the-api-section-what-now" aria-label="Permalink to &quot;The container does not compile after I changed the api: section. What now?&quot;">​</a></h2><p>Read the whole message. The <a href="/nette-api/pr-preview/pr-235/guide/di-extension.html">DI extension</a> checks the configuration and the <a href="/nette-api/pr-preview/pr-235/guide/attributes.html">endpoint attributes</a> when the container is compiled, and each message says what is wrong, where (the neon key, or the class and the attribute) and how to fix it, often with an example or a &quot;Did you mean&quot; suggestion. For example, <code>version: v1</code> fails with <code>the &#39;v&#39; is added to the URL automatically (/v1/users). Use for example version: 1.</code> Settings that would silently do nothing also fail, such as an attribute on a method instead of the class, a <code>cors: mode</code> next to <code>allowedOrigins</code>, or a quoted <code>&#39;@service&#39;</code> reference.</p><h2 id="how-do-i-publish-openapi" tabindex="-1">How do I publish OpenAPI? <a class="header-anchor" href="#how-do-i-publish-openapi" aria-label="Permalink to &quot;How do I publish OpenAPI?&quot;">​</a></h2><p>Register <code>OpenApiHandler</code> as an endpoint. See <a href="/nette-api/pr-preview/pr-235/guide/openapi.html">OpenAPI</a>.</p><h2 id="how-do-i-upgrade-from-2-x" tabindex="-1">How do I upgrade from 2.x? <a class="header-anchor" href="#how-do-i-upgrade-from-2-x" aria-label="Permalink to &quot;How do I upgrade from 2.x?&quot;">​</a></h2><p>Follow the <a href="/nette-api/pr-preview/pr-235/upgrade.html">upgrade guide</a> and the <a href="/nette-api/pr-preview/pr-235/changelog.html">changelog</a>.</p><h2 id="is-there-a-complete-project-i-can-run" tabindex="-1">Is there a complete project I can run? <a class="header-anchor" href="#is-there-a-complete-project-i-can-run" aria-label="Permalink to &quot;Is there a complete project I can run?&quot;">​</a></h2><p>Yes, 13 of them, tested in CI: see <a href="/nette-api/pr-preview/pr-235/examples/">Examples</a>.</p>',27)])])}const g=a(n,[["render",i]]);export{u as __pageData,g as default};
